/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.ndimage import label
f=np.load('source_pixels.npz')['rgb']
for t in [0,10,20,30,40,50,60,70,80,95]:
 a=f[t].astype(float);r,g,b=a.transpose(2,0,1)
 print('\\nFRAME',t)
 masks={'Y':(r>g*1.06)&(g>b*1.15)&(r>100),'B':(b>r*1.25)&(b>g*1.08),'R':(r>g*1.25)&(r>b*1.25),'G':(g>r*1.15)&(g>b*1.05),'dark':(r+g+b<330)}
 for n,m in masks.items():
  labs,num=label(m)
  objs=[]
  for k in range(1,num+1):
   yy,xx=np.where(labs==k)
   if len(xx)>5:objs.append((len(xx),tuple(np.round([xx.mean(),yy.mean()],2)),(xx.min(),yy.min(),xx.max(),yy.max())))
  print(n,objs)
 if t in [0,30,60,95]:
  chars=np.full((72,128),' ',dtype='<U1')
  for y in range(72):
   for x in range(128):
    for n,m in masks.items():
     if m[2*y:2*y+2,2*x:2*x+2].sum()>1:chars[y,x]='#' if n=='dark' else n
  for y in range(10,72):
   line=''.join(chars[y]);
   if line.strip():print(f'{y*2:3}',line)
PY"
